// CONFIGURACIÓN
const ADMIN_PASSWORD = "malaga"; // <--- CAMBIA ESTO POR TU CONTRASEÑA

function doGet(e) {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  
  // 1. Lectura de Datos (Data)
  var sheetData = ss.getSheetByName("Data");
  if (!sheetData) {
    sheetData = ss.insertSheet("Data");
    sheetData.appendRow(["FECHA", "ALUMNO", "AVATAR", "ASIGNATURA", "SITUACION", "NOTA", "TIEMPO"]);
  }
  var dataValues = sheetData.getDataRange().getValues();
  var rows = dataValues.slice(1);
  var result = rows.map(function(row) {
    return {
      date: row[0], 
      username: row[1], 
      avatar: row[2], 
      category: row[3], 
      situation: row[4], 
      grade: row[5], 
      time: row[6]
    };
  });
  
  // 2. Lectura de Configuración (Config)
  var sheetConfig = ss.getSheetByName("Config");
  var allConfigs = {};
  if (sheetConfig) {
     var cell = sheetConfig.getRange("A1").getValue();
     if (cell) {
       try { allConfigs = JSON.parse(cell); } catch(e) {}
     }
  }
  
  return ContentService.createTextOutput(JSON.stringify({
    data: result,
    config: allConfigs
  })).setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  var lock = LockService.getScriptLock();
  lock.tryLock(10000);
  
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var payload = JSON.parse(e.postData.contents);
    
    // --- AUTENTICACIÓN ADMIN ---
    if (payload.action === 'admin_login') {
       var result = (payload.password === ADMIN_PASSWORD) ? "success" : "error";
       return ContentService.createTextOutput(JSON.stringify({ result: result }))
              .setMimeType(ContentService.MimeType.JSON);
    }
    
    if (payload.action === 'save_config') {
       // --- GUARDAR CONFIGURACIÓN ---
       var sheetConfig = ss.getSheetByName("Config");
       if (!sheetConfig) sheetConfig = ss.insertSheet("Config");
       
       var currentData = {};
       var cellVal = sheetConfig.getRange("A1").getValue();
       if (cellVal) {
          try { currentData = JSON.parse(cellVal); } catch(e) {}
       }
       
       var appId = payload.appId || 'default';
       currentData[appId] = payload.config;
       
       sheetConfig.getRange("A1").setValue(JSON.stringify(currentData));
       return ContentService.createTextOutput("Config Saved");
       
    } else {
       // --- GUARDAR REGISTRO DE ALUMNO ---
       var sheetData = ss.getSheetByName("Data");
       if (!sheetData) sheetData = ss.insertSheet("Data");
       
       sheetData.appendRow([ 
         payload.date || new Date(), 
         payload.username, 
         payload.avatar, 
         payload.category, 
         payload.situation, 
         payload.grade, 
         payload.time 
       ]);
       
       return ContentService.createTextOutput("Record Saved");
    }
  } catch(err) {
    return ContentService.createTextOutput("Error: " + err.toString());
  } finally {
    lock.releaseLock();
  }
}
